package com.pustibondhu.backend.health.medical.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.Objects;

/**
 * Represents a generic active chemical substance (e.g. Metformin).
 *
 * <p>Module: HEALTH | Table: drug_ingredients | Migration: V100 | Author: Ahsan</p>
 */
@Entity
@Table(name = "drug_ingredients")
public class DrugIngredient {

    /** Primary key (BIGSERIAL, auto-generated by the database). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false)
    private Long id;

    /** Unique English generic name. */
    @Column(name = "name_en", nullable = false, unique = true, length = 150)
    private String nameEn;

    /** Bangla generic name (optional). */
    @Column(name = "name_bn", length = 150)
    private String nameBn;

    /** Drug class, e.g. Biguanide (optional). */
    @Column(name = "drug_class", length = 100)
    private String drugClass;

    /** Required by JPA. */
    public DrugIngredient() {
    }

    /** Creates a fully populated instance. */
    public DrugIngredient(Long id, String nameEn, String nameBn, String drugClass) {
        this.id = id;
        this.nameEn = nameEn;
        this.nameBn = nameBn;
        this.drugClass = drugClass;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getNameEn() {
        return nameEn;
    }

    public void setNameEn(String nameEn) {
        this.nameEn = nameEn;
    }

    public String getNameBn() {
        return nameBn;
    }

    public void setNameBn(String nameBn) {
        this.nameBn = nameBn;
    }

    public String getDrugClass() {
        return drugClass;
    }

    public void setDrugClass(String drugClass) {
        this.drugClass = drugClass;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof DrugIngredient that)) return false;
        return id != null && Objects.equals(id, that.id);
    }

    @Override
    public int hashCode() {
        return getClass().hashCode();
    }

    @Override
    public String toString() {
        return "DrugIngredient{id=" + id
                + ", nameEn='" + nameEn + '\''
                + ", nameBn='" + nameBn + '\''
                + ", drugClass='" + drugClass + '\'' + '}';
    }
}